import sys

import numpy as np
import wgpu

SHADER = """
struct Dims { w: u32, h: u32 };

@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> dims: Dims;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= dims.w || y >= dims.h) {
        return;
    }
    let xl = select(x - 1u, 0u, x == 0u);
    let xr = min(x + 1u, dims.w - 1u);
    let yu = select(y - 1u, 0u, y == 0u);
    let yd = min(y + 1u, dims.h - 1u);
    let s = 4u * src[y * dims.w + x]
        + src[y * dims.w + xl] + src[y * dims.w + xr]
        + src[yu * dims.w + x] + src[yd * dims.w + x];
    dst[y * dims.w + x] = s / 8u;
}
"""


def parse(text):
    tok = text.split()
    w, h, steps = int(tok[0]), int(tok[1]), int(tok[2])
    grid = np.array(tok[3:3 + w * h], dtype=np.uint32)
    if grid.size != w * h:
        raise ValueError("not enough cells")
    return w, h, steps, grid


def diffuse(w, h, steps, grid):
    """Run `steps` stencil steps on the GPU; returns a flat uint32 array."""
    if steps == 0:
        return grid
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    nbytes = grid.nbytes
    bufs = [device.create_buffer(size=nbytes, usage=usage) for _ in range(2)]
    device.queue.write_buffer(bufs[0], 0, grid.tobytes())
    dims = device.create_buffer_with_data(
        data=np.array([w, h, 0, 0], dtype=np.uint32).tobytes(),
        usage=wgpu.BufferUsage.UNIFORM,
    )
    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    layout = pipeline.get_bind_group_layout(0)
    groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": bufs[i], "offset": 0, "size": nbytes}},
                {"binding": 1, "resource": {"buffer": bufs[1 - i], "offset": 0, "size": nbytes}},
                {"binding": 2, "resource": {"buffer": dims, "offset": 0, "size": 16}},
            ],
        )
        for i in range(2)
    ]
    gx, gy = (w + 7) // 8, (h + 7) // 8
    enc = device.create_command_encoder()
    # one pass per step so writes of a step are visible to the next
    for s in range(steps):
        p = enc.begin_compute_pass()
        p.set_pipeline(pipeline)
        p.set_bind_group(0, groups[s % 2])
        p.dispatch_workgroups(gx, gy, 1)
        p.end()
    device.queue.submit([enc.finish()])
    out = device.queue.read_buffer(bufs[steps % 2])
    return np.frombuffer(out, dtype=np.uint32, count=w * h).copy()


def main():
    with open(sys.argv[1]) as f:
        w, h, steps, grid = parse(f.read())
    res = diffuse(w, h, steps, grid)
    rows = res.reshape(h, w)
    lines = [" ".join(map(str, r)) for r in rows.tolist()]
    lines.append("SUM %d" % int(res.astype(np.uint64).sum()))
    sys.stdout.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
