import random
import subprocess
import sys
from pathlib import Path

import pytest

MAIN = Path(__file__).parent / "main.py"


def ref(w, h, steps, g):
    for _ in range(steps):
        n = [[0] * w for _ in range(h)]
        for y in range(h):
            for x in range(w):
                n[y][x] = (4 * g[y][x] + g[y][max(x - 1, 0)] + g[y][min(x + 1, w - 1)]
                           + g[max(y - 1, 0)][x] + g[min(y + 1, h - 1)][x]) // 8
        g = n
    return g


@pytest.mark.parametrize("w,h,steps", [(1, 1, 5), (1, 7, 3), (9, 1, 4), (5, 4, 0), (17, 13, 20), (33, 9, 1)])
def test_matches_reference(tmp_path, w, h, steps):
    g = [[random.randint(0, 1000000) for _ in range(w)] for _ in range(h)]
    p = tmp_path / "in.txt"
    p.write_text(f"{w} {h} {steps}\n" + "\n".join(" ".join(map(str, r)) for r in g) + "\n")
    r = subprocess.run([sys.executable, str(MAIN), str(p)], capture_output=True, text=True, check=True)
    exp = ref(w, h, steps, g)
    want = "\n".join(" ".join(map(str, r)) for r in exp) + f"\nSUM {sum(map(sum, exp))}\n"
    assert r.stdout == want
